 export const TASA_IVA = 0.13;

+// La tasa de IVA se configura por entorno con TASA_IVA (0 a 1); sin definir vale TASA_IVA.
+export function tasaIva(env = process.env) {
+  const valor = env.TASA_IVA;
+  if (valor === undefined) return TASA_IVA;
+  const tasa = /^\s*\d+(\.\d+)?\s*$/.test(valor) ? Number(valor) : NaN;
+  if (!(tasa >= 0 && tasa <= 1)) throw new RangeError(`TASA_IVA inválida: ${JSON.stringify(valor)} (debe ser un número entre 0 y 1)`);
+  return tasa;
+}
